<section class="panel"><p class="muted">Registre um pedido administrativo para um cliente cadastrado. O estoque será validado e atualizado automaticamente.</p><form method="post" action="index.php?entidade=pedidos&acao=salvar" class="checkout-form"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><div class="field"><label for="usuario_id">Cliente</label><select id="usuario_id" name="usuario_id" required><option value="">Selecione um cliente</option><?php foreach ($clientes as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['nome']) ?> — <?= e($c['email']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="game_id">Jogo</label><select id="game_id" name="game_id" required><option value="">Selecione um jogo</option><?php foreach ($games as $g): ?><option value="<?= (int)$g['id'] ?>" <?= (int)$g['estoque']<1?'disabled':'' ?>><?= e($g['titulo']) ?> · <?= (int)$g['estoque'] ?> em estoque</option><?php endforeach; ?></select></div><div class="field"><label for="quantidade">Quantidade</label><input id="quantidade" type="number" name="quantidade" min="1" value="1" required></div><div class="field"><label for="endereco">Endereço de entrega</label><input id="endereco" name="endereco" maxlength="255" required></div><div class="checkout-form-row"><div class="field"><label for="cidade">Cidade / Estado</label><input id="cidade" name="cidade" required></div><div class="field"><label for="cep">CEP</label><input id="cep" name="cep" required></div></div><div class="field"><label for="forma_pagamento">Pagamento</label><select id="forma_pagamento" name="forma_pagamento"><option value="pix">Pix</option><option value="cartao">Cartão (simulação)</option><option value="boleto">Boleto (simulação)</option></select></div><div class="quick-actions"><button class="btn btn-primary" <?= (!$clientes||!$games)?'disabled':'' ?>>Registrar pedido</button><a class="btn btn-secondary" href="index.php?entidade=pedidos">Cancelar</a></div></form></section>
